stem:
Com o error handler central da aula, qual é a resposta de `GET /lugares/999`?

```js
app.get("/lugares/:id", (req, res) => {
  throw new ErroNaoEncontrado("Lugar não encontrado.");
});

app.use((erro, req, res, next) => {
  if (erro instanceof ErroApi) {
    const corpo = { erro: erro.message };
    if (erro.campo) corpo.campo = erro.campo;
    return res.status(erro.statusCode).json(corpo);
  }
  console.error(erro);
  res.status(500).json({ erro: "Erro interno do servidor." });
});
```

